interface.definition:
if(
  ri!isInitialAmend,
  /*SUBMIT for INITIAL AMEND ONLY*/
  #"SYSTEM_SYSRULES_ButtonWidget"(
    label: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155707",
    value:  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155707",
    saveInto: {
      ri!buttonValue,
      a!save(
        ri!rotationalAskDetails,
        ri!selectedBUs
      ),
      /*update RA versions by 1 in lines above, and update mod by, mod on, created on, created by*/
      #"SYSTEM_SYSRULES_forEach"(
        items: ri!rotationalAskDetails,
        expression: {
          a!save(
            fv!item.version,
            ri!newVersion
          ),
          a!save(
            {
              fv!item.modifiedBy,
              fv!item.createdBy
            },
            loggedInUser()
          ),
          a!save(
            {
              fv!item.createdOn,
              fv!item.modifiedOn
            },
            now()
          ),
          a!save(
            fv!item.askDetailId,
            null
          ),
          a!save(
            fv!item.iscompleted,
            false
          )
        }
      ),
      /*when we initially amend we need to create a new task row for the new amended version*/
      a!save(
        ri!task,
        'type!{urn:com:appian:types:CAW}CAW_Task'(
          requestId: ri!ask.askId,
          taskName: if(ri!region=#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11605098",/*ri!ask.fYear&" "&*/ri!ask.askName&" Rotational ASK - Amended",
          ri!ask.fYear&" "&ri!region&" Rotational ASK - Amended"),
          moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164387",
          statusId: ri!nextStatusId, 
          assigneeId: ri!assigneeId,
          isAssigneeGroup: tointeger(index(ri!assignee, "totalCount", null)) > 1,
          isLocked: false,
          isTaskAmend: true,
          isApproved: false,
          isCompleted: false,
          version: ri!newVersion,
          createdBy: loggedInUser(),
          createdOn: now(),
          modifiedBy: loggedInUser(),
          modifiedOn: now()
        )
      ),
      /*when we initially amend we need to update the ask*/
      a!save(
        ri!ask.isCompleted,
        false
      ),
      a!save(
        ri!ask.version,
        ri!newVersion
      ),
      a!save(
        ri!ask.statusId,
        ri!nextStatusId
      ),
      a!save(
        ri!ask.modifiedBy,
        loggedInUser()
      ),
      a!save(
        ri!ask.modifiedOn,
        now()
      ),
      /*only create and save a comment if there is one to write*/
      if(
        a!isNullOrEmpty(ri!comment.comment),
        {},
        a!save(
          ri!comment,
          'type!{urn:com:appian:types:CAW}CAW_Comment'(
            requestId: ri!ask.askId,
            moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164387",
            comment: ri!comment.comment,
            isActive: true,
            isDraft: false,
            version: ri!newVersion,
            createdBy:loggedInUser(),
            createdOn: now(),
            modifiedBy:loggedInUser(),
            modifiedOn: now()
          )
        )
      ),
      /*audit history for the intial amended ASK as well as the save and exit on task*/
      a!save(
        ri!auditHistory,
        {
          'type!{urn:com:appian:types:CAW}CAW_Audit'(
            taskId: ri!task.taskId,
            requestId: ri!ask.askId,
            version: ri!newVersion,
            moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164387",
            statusId: ri!task.statusId,
            action: "Submitted Task",
            description: if(
              tointeger(ri!nextStatusId)=index(#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063",1,null),
              "Submitted for PPL review",
              if(
                tointeger(ri!nextStatusId)=index(#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063",2,null),
                "Submitted for "&#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3374322"(ri!selectedApprover)&" review",
                if(
                  tointeger(ri!nextStatusId)=index(#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063",3,null),
                  "Submitted for APPP review",
                  if(
                    tointeger(ri!nextStatusId)=index(#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063",4,null),
                    "Submitted for DPP PIC review",
                    null
                  )
                )
              )
            ),
            createdBy: loggedInUser(),
            createdOn: now()
          ),
          /*We only want the amended ASK created audit the first time they save and exit or submit*/
          if(
            a!isNullOrEmpty(ri!task.taskId),
            'type!{urn:com:appian:types:CAW}CAW_Audit'(
              requestId: ri!ask.askId,
              version: ri!newVersion,
              moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164387",
              statusId:  ri!task.statusId,
              action: "ASK Amended",
              description: "Rotational ASK V"&ri!newVersion&" created",
              createdBy: loggedInUser(),
              createdOn: now()
            ),
            {}
          )
        }
      )
    },
    validationGroup: "SUBMIT",
    submit: true,
    style: "PRIMARY",
    showWhen: and(
      or(
        not(ri!isReview),
        ri!task.statusId = #"_a-0000e825-ace1-8000-9c24-011c48011c48_6791426"
      ), 
      ri!isInitialAmend = true,
      ri!isEdit = false
    ),
    validate: true,
    confirmMessage: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3215506"
  ),
  #"SYSTEM_SYSRULES_ButtonWidget"(
    label: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155707",
    value:  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155707",
    saveInto: {
      ri!buttonValue,
      a!save(
        ri!rotationalAskDetails,
        ri!selectedBUs
      ),
      if(
        ri!isEdit,
        {
          if(
            ri!isComplete,
            {
              #"SYSTEM_SYSRULES_forEach"(
                items: ri!rotationalAskDetails,
                expression: {
                  a!save(
                    fv!item.iscompleted,
                    true
                  ),
                  a!save(
                    fv!item.modifiedBy,
                    loggedInUser()
                  ),
                  a!save(
                    fv!item.modifiedOn,
                    now()
                  )
                }
              ),
              a!save(ri!ask.latestCompletedVersion, ri!task.version)
            },
            {
              #"SYSTEM_SYSRULES_forEach"(
                items: ri!rotationalAskDetails,
                expression: {
                  a!save(
                    fv!item.modifiedBy,
                    loggedInUser()
                  ),
                  a!save(
                    fv!item.modifiedOn,
                    now()
                  )
                }
              )
            }
          ),
          /*ASK updates*/
          a!save(ri!ask.statusId, if(ri!isComplete=true,#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3344039",ri!nextStatusId)),
          a!save(ri!ask.isCompleted, ri!isComplete=true),
          a!save(ri!ask.modifiedBy, #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3052910"(loggedInUser())),
          a!save(ri!ask.modifiedOn, now()),
          /*Task updates*/
          a!save(ri!task.statusId, if(ri!isComplete,#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3344039",ri!nextStatusId)),
          a!save(ri!task.assigneeId, if(ri!isComplete,null,ri!assigneeId)),
          a!save(ri!task.isAssigneeGroup, if(ri!isComplete,null,tointeger(index(ri!assignee, "totalCount", null)) > 1)),
          a!save(ri!task.isCompleted, ri!isComplete=true),
          a!save(ri!task.modifiedBy, loggedInUser()),
          a!save(ri!task.modifiedOn, now())
        },
        {
          a!save(
            ri!ask,
            'type!{urn:com:appian:types:CAW}CAW_Ask'(
              fYear: ri!ask.fYear,
              regionId: ri!ask.regionId,
              askName: ri!ask.askName,
              typeId: ri!ask.typeId,
              statusId: ri!nextStatusId,
              isActive: true,
              isCompleted: false,
              version: 1,
              latestCompletedVersion: 0,
              createdBy: loggedInUser(),
              createdOn: now(),
              modifiedBy: loggedInUser(),
              modifiedOn: now()
            )
          ),
          a!save(
            ri!task,
            'type!{urn:com:appian:types:CAW}CAW_Task'(
              taskName:if(ri!region=#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11605098",concat(
                /*index(ri!ask, "fYear",tointeger(null)) & 
                " " &*/ "Rotational " & ri!ask.askName
              ),
              concat(
                index(ri!ask, "fYear",tointeger(null)) & 
                " " & ri!region & 
                " Rotational"
              )),
              moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164387",
              statusId: ri!nextStatusId, 
              assigneeId: ri!assigneeId,
              isAssigneeGroup: tointeger(index(ri!assignee, "totalCount", null)) > 1,
              isLocked: false,
              isTaskAmend: false,
              isCompleted: false,
              version: 1,
              createdBy: loggedInUser(),
              createdOn: now(),
              modifiedBy: loggedInUser(),
              modifiedOn: now()
            )
          )
        }
      ),
      /*COMMENT LOGIC*/
      if(
        and(
          a!isNullOrEmpty(ri!previousComment),
          a!isNotNullOrEmpty(ri!comment.comment)
        ),
        /*Create the whole comment CDT*/
        a!save(
          ri!comment,
          'type!{urn:com:appian:types:CAW}CAW_Comment'(
            commentId: index(ri!comment,"commentId",null),
            requestId: ri!ask.askId,
            moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164387",
            comment: ri!comment.comment,
            isDraft: false,
            isActive: true,
            version: ri!task.version,
            createdBy: loggedInUser(),
            createdOn: now(),
            modifiedBy: loggedInUser(),
            modifiedOn: now()
          )
        ),
        if(
          and(
            a!isNotNullOrEmpty(ri!previousComment),
            a!isNullOrEmpty(ri!comment.comment)
          ),
          /*Clear the comment/Delete the row of data */
          a!save(ri!commentIDtoDelete,ri!comment.commentId),
          if(
            ri!comment.comment <> ri!previousComment,
            /*update the comment fields*/
            {
              a!save(ri!comment.modifiedBy, loggedInUser()),
              a!save(ri!comment.modifiedOn, now()),
              a!save(ri!comment.isDraft,false)
            },
            a!save(ri!comment.isDraft,false)
          )
        )
      ),
      /*ALL Cases for Audit History*/
      a!save(
        ri!auditHistory,
        {
          if(
            ri!isComplete,
            'type!{urn:com:appian:types:CAW}CAW_Audit'(
              taskId: ri!task.taskId,
              requestId: ri!ask.askId,
              version: ri!task.version,
              moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164387",
              statusId:  ri!task.statusId,
              action: "Completed",
              description: "Rotational ASK marked as complete",
              createdBy: loggedInUser(),
              createdOn: now()
            ),
            'type!{urn:com:appian:types:CAW}CAW_Audit'(
              taskId: ri!task.taskId,
              requestId: ri!ask.askId,
              version: ri!task.version,
              moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164387",
              statusId:  ri!task.statusId,
              action: "Submitted Task",
              description: if(
                tointeger(ri!nextStatusId)=index(#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063",1,null),
                "Submitted for PPL review",
                if(
                  tointeger(ri!nextStatusId)=index(#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063",2,null),
                  concat("Submitted for "&#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3374322"(ri!selectedApprover)&" review"),
                  if(
                    tointeger(ri!nextStatusId)=index(#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063",3,null),
                    "Submitted for APPP review",
                    if(
                      tointeger(ri!nextStatusId)=index(#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063",4,null),
                      "Submitted for DPP PIC review",
                      null
                    )
                  )
                )
              ),
              createdBy: loggedInUser(),
              createdOn: now()
            ),
          ),
          /*We only want the ASK created audit the first time the ASK is saved*/
          if(
            a!isNullOrEmpty(ri!task.taskId),
            'type!{urn:com:appian:types:CAW}CAW_Audit'(
              version: 1,
              moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164387",
              statusId:  ri!task.statusId,
              action: "Rotational ASK Created",
              description: "Rotational ASK V1 created",
              createdBy: loggedInUser(),
              createdOn: now()
            ),
            null
          )
        }
      )
    },
    validationGroup: "SUBMIT",
    submit: true,
    style: "PRIMARY",
    showWhen: and(
      or(
        not(ri!isReview),
        ri!task.statusId = #"_a-0000e825-ace1-8000-9c24-011c48011c48_6791426"
      ),
      ri!isInitialAmend = false
    ),
    validate: true,
    confirmMessage: if(
      ri!isComplete,
      #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3576172",
      #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3215506"
    )
  )
)
